  const p = validate({ ...fm, startDate: fm.start_date, budgetDate: fm.budget_date, budgetFx: fm.budget_fx, coverIcon: fm.cover_icon, coverColor: fm.cover_color }, path);
  const parsed = table.parseTable(text, path);
